#!/bin/sh
case "$1 $2" in
  "auth status") echo '{"loggedIn":true}'; exit 0 ;;
  "plugin list") echo "[]"; exit 0 ;;
  "--version "*) echo "2.1.309 (Claude Code)"; exit 0 ;;
esac
echo "== claude run"
prev=""
for a in "$@"; do
  case $prev in
    --append-system-prompt) echo "arg: <prompt>" ;;
    --settings) echo "arg: $a"; if [ -f "$a" ]; then echo "settings-file:"; cat "$a"; echo; fi ;;
    --mcp-config) echo "arg: $a"; if [ -f "$a" ]; then echo "mcp-file:"; cat "$a"; fi ;;
    *) echo "arg: $a" ;;
  esac
  prev=$a
done
env | grep -E '^(KITH_(AGENT|AGENT_VERSION|PROVIDER|ACCOUNT|ACCOUNT_ID|RUN_KIND|RUN_LABEL|RESUMED_FROM|ASK_ID|ASK_TOKEN|ASK_SOCKET|PERSON|OWNER|VIA|MODEL|EFFORT|PROJECT|REVOKE_SEEN|CLAUDE_ARGS|LAUNCH_KIND|LAUNCH_ASK_ID|LAUNCH_SID_FILE|TERMINAL_SESSION|RUN_TOKEN|RUN_SOCKET)|CLAUDE_CODE_ARTIFACT|CLAUDE_CONFIG_DIR)=' | sort
echo "pid=$$"
mine=no
for f in "${KITH_STATE:-/none}"/live/terminal/*.claim "${KITH_STATE:-/none}"/live/terminal/proc-*; do
  [ -f "$f" ] && grep -q "\"pid\": *$$[,}]" "$f" 2>/dev/null && mine=yes
done
echo "claim-names-this-process: $mine"
echo "claims: $(ls "${KITH_STATE:-/none}/live/terminal" 2>/dev/null | tr '\n' ' ')"
exit 0

